package com.aveniq.kitchen.printing;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.JSONObject;
import java.io.IOException;
public class AttemptEngineTest {
 static final class MemoryJournal implements AttemptEngine.Journal {JSONObject value;boolean failConsumed;public JSONObject read(){return value;}public void save(JSONObject next)throws IOException{if(failConsumed&&next.optString("stage").equals("consumed"))throw new IOException("simulated fsync failure");try{value=new JSONObject(next.toString());}catch(org.json.JSONException error){throw new IOException(error);}}public void clear(){value=null;}}
 static final class Backend implements AttemptEngine.Rpc {MemoryJournal journal;boolean lostBegin,failAck;boolean began;int finishes;Backend(MemoryJournal journal){this.journal=journal;}public Object call(String name,JSONObject args)throws Exception{if(name.equals("begin_kitchen_print_attempt")){assertEquals("before_begin",journal.read().getString("stage"));began=true;if(lostBegin)throw new IOException("lost begin response");return new JSONObject().put("restaurantId","tenant").put("operatorId","operator").put("snapshot",new JSONObject()).put("destination",new JSONObject().put("configRevision",1));}if(name.equals("inspect_kitchen_print_recovery"))return new JSONObject().put("jobId","job").put("restaurantId","tenant").put("state",began?"dispatching":"leased").put("attemptStarted",began);if(name.equals("finish_kitchen_print_attempt")){finishes++;if(failAck){failAck=false;throw new IOException("lost acknowledgement");}return new JSONObject().put("accepted",true).put("outcome",args.getString("p_outcome")).put("state",args.getString("p_outcome"));}throw new AssertionError(name);}}
 private JSONObject claim()throws Exception{return new JSONObject().put("jobId","job").put("claimToken","claim").put("configRevision",1);}
 private AttemptEngine.Registration registration(){return new AttemptEngine.Registration("device","secret","tenant","operator");}
 @Test public void fsyncBeforeBeginAndConsumedBeforeSocketAndOnlyOneOutput()throws Exception{MemoryJournal journal=new MemoryJournal();Backend api=new Backend(journal);int[] sends={0};AttemptEngine engine=new AttemptEngine(api,journal,(destination,bytes)->{assertEquals("consumed",journal.read().getString("stage"));sends[0]++;return new TcpPrinter.Result("transmitted",null);},snapshot->new byte[]{1});assertEquals("transmitted",engine.run(claim(),registration()).state());assertEquals(1,sends[0]);assertNull(journal.read());}
 @Test public void lostBeginResponseNeverSendsAndRecoversAsUncertain()throws Exception{MemoryJournal journal=new MemoryJournal();Backend api=new Backend(journal);api.lostBegin=true;int[] sends={0};AttemptEngine engine=new AttemptEngine(api,journal,(d,b)->{sends[0]++;return new TcpPrinter.Result("transmitted",null);},s->new byte[]{1});try{engine.run(claim(),registration());fail();}catch(IOException expected){}assertEquals("uncertain",engine.recover(registration()).state());assertEquals(0,sends[0]);}
 @Test public void lostFinishResponseRetriesAcknowledgementOnly()throws Exception{MemoryJournal journal=new MemoryJournal();Backend api=new Backend(journal);api.failAck=true;int[] sends={0};AttemptEngine engine=new AttemptEngine(api,journal,(d,b)->{sends[0]++;return new TcpPrinter.Result("transmitted",null);},s->new byte[]{1});try{engine.run(claim(),registration());fail();}catch(IOException expected){}assertEquals("outcome",journal.read().getString("stage"));engine.recover(registration());assertEquals(1,sends[0]);assertEquals(2,api.finishes);}
 @Test public void consumedJournalWriteFailurePreventsSocketAndRecoveryDoesNotReplay()throws Exception{MemoryJournal journal=new MemoryJournal();journal.failConsumed=true;Backend api=new Backend(journal);int[] sends={0};AttemptEngine engine=new AttemptEngine(api,journal,(d,b)->{sends[0]++;return new TcpPrinter.Result("transmitted",null);},s->new byte[]{1});try{engine.run(claim(),registration());fail();}catch(IOException expected){}journal.failConsumed=false;engine.recover(registration());assertEquals(0,sends[0]);}
 @Test public void processDeathAfterConsumeQuarantinesWithoutSecondWrite()throws Exception{MemoryJournal journal=new MemoryJournal();Backend api=new Backend(journal);int[] sends={0};AttemptEngine engine=new AttemptEngine(api,journal,(d,b)->{sends[0]++;throw new AssertionError("simulated process death");},s->new byte[]{1});try{engine.run(claim(),registration());fail();}catch(AssertionError expected){}assertEquals("consumed",journal.read().getString("stage"));engine.recover(registration());assertEquals(1,sends[0]);}
}
